class Bowl<T> {
    private T thing;

    void put(T thing) {
        this.thing = thing;
    }

    T take() {
        return thing;
    }
}

public class Main {
    public static void main(String[] args) {
        Bowl<Integer> b = new Bowl<>();
        b.put(10);
        System.out.println(b.take() + 5);
    }
}

